CREATE TABLE IF NOT EXISTS platform_stabilization_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_type text NOT NULL DEFAULT 'manual', status text NOT NULL DEFAULT 'running', checks jsonb NOT NULL DEFAULT '[]'::jsonb, passed_count integer NOT NULL DEFAULT 0, failed_count integer NOT NULL DEFAULT 0, warning_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz)